for (const value of [null, undefined, 17, {}, { trim: () => 'x' }]) {
  const result = lookupAccount(value, {}, {});
  assert.ok(result instanceof Promise);
  await assert.rejects(result, { name: 'TypeError', message: 'key must be a string' });
}
assert.deepEqual(await lookupAccount(' ', {}, { lookup() { throw Error('unexpected read'); } }), { kind: 'missing' });
let resolveLookup;
let allowed = true;
const account = { id: 0, label: '', private: 'retained when authorized' };
const pending = lookupAccount(' zero ', { canRead: id => { assert.equal(id, 0); return allowed; } }, { lookup: key => { assert.equal(key, 'zero'); return new Promise(resolve => { resolveLookup = resolve; }); } });
allowed = false;
resolveLookup(account);
assert.deepEqual(await pending, { kind: 'denied' });
assert.deepEqual(await lookupAccount('zero', { canRead: () => true }, { lookup: async () => account }), { kind: 'found', account });
assert.deepEqual(await lookupAccount('absent', {}, { lookup: async () => null }), { kind: 'missing' });
const transient = Object.assign(new Error('down'), { code: 'TEMP_DOWN' });
assert.deepEqual(await lookupAccount('x', {}, { lookup: async () => { await Promise.resolve(); throw transient; } }), { kind: 'unavailable' });
const unknown = new Error('unknown');
await assert.rejects(lookupAccount('x', {}, { lookup: async () => { throw unknown; } }), error => error === unknown);

function deferred() {
  let resolve, reject;
  const promise = new Promise((yes, no) => { resolve = yes; reject = no; });
  return { promise, resolve, reject };
}
