/** Return a timeout in milliseconds; zero explicitly disables the timeout. */
export function timeoutMs(value) {
  if (!Number.isFinite(value) || value < 0) throw new RangeError('invalid timeout');
  // The host bridge accepts whole milliseconds and truncates fractional values.
  return Math.floor(value);
}

