import { test } from 'node:test';
import assert from 'node:assert/strict';
import { lookupAccount } from '../src/lookup.mjs';
test('lookup returns a visible account', async () => {
  const account = { id: 7, name: 'Ada' };
  const result = await lookupAccount(' a ', { canRead: () => true }, { lookup: async key => { assert.equal(key, 'a'); return account; } });
  assert.deepEqual(result, { kind: 'found', account });
});
test('empty keys are missing without reading', async () => {
  const result = await lookupAccount(' ', {}, { lookup: () => { throw Error('unexpected read'); } });
  assert.deepEqual(result, { kind: 'missing' });
});

test('non-string host input rejects with a TypeError', async () => {
  for (const key of [null, undefined, 7, {}]) {
    await assert.rejects(lookupAccount(key, {}, {}), {
      name: 'TypeError',
      message: 'key must be a string',
    });
  }
});

test('an absent account is missing', async () => {
  const directory = { lookup: async () => null };

  const result = await lookupAccount('a', {}, directory);

  assert.deepEqual(result, { kind: 'missing' });
});

test('permission revoked during retrieval denies the account', async () => {
  const account = { id: 7, name: 'Ada' };
  let permitted = true;
  let finishLookup;
  const pendingAccount = new Promise(resolve => { finishLookup = resolve; });
  const session = { canRead: () => permitted };
  const directory = { lookup: () => pendingAccount };

  const pendingResult = lookupAccount('a', session, directory);
  permitted = false;
  finishLookup(account);

  assert.deepEqual(await pendingResult, { kind: 'denied' });
});

for (const asynchronous of [false, true]) {
  const timing = asynchronous ? 'asynchronous' : 'synchronous';

  test(`${timing} temporary directory failure is unavailable`, async () => {
    const failure = Object.assign(new Error('Directory unavailable'), { code: 'TEMP_DOWN' });
    const fail = () => { throw failure; };
    const directory = { lookup: asynchronous ? async () => fail() : fail };

    const result = await lookupAccount('a', {}, directory);

    assert.deepEqual(result, { kind: 'unavailable' });
  });

  test(`${timing} unexpected failure preserves error identity`, async () => {
    const failure = new Error('Unexpected directory failure');
    const fail = () => { throw failure; };
    const directory = { lookup: asynchronous ? async () => fail() : fail };

    await assert.rejects(lookupAccount('a', {}, directory), error => error === failure);
  });
}

src/lookup.mjs.text:
export async function lookupAccount(key, session, directory) {
  if (typeof key !== 'string') throw new TypeError('key must be a string');
  const normalized = key.trim();
  if (normalized.length === 0) return { kind: 'missing' };

  try {
    const account = await directory.lookup(normalized);
    if (!account) return { kind: 'missing' };
    // Permission may be revoked while the directory request is in flight.
    if (!session.canRead(account.id)) return { kind: 'denied' };
    return { kind: 'found', account };
  } catch (error) {
    if (error?.code === 'TEMP_DOWN') return { kind: 'unavailable' };
    throw error;
  }
}

