export async function publishReceipt(receipt, transport) {
  const lease = await transport.acquire();
  try {
    // The transport must keep its lease until send settles, including rejection.
    const payload = JSON.stringify(receipt);
    return await lease.send(payload);
  } finally {
    await lease.release();
  }
}

